# Score tools 1-5 on criteria; weights sum to 1. Then change the weights and re-check the winner.
scores = {
    "ToolA": {"quality": 5, "cost": 2, "controls": 3},
    "ToolB": {"quality": 4, "cost": 4, "controls": 4},
    "ToolC": {"quality": 3, "cost": 5, "controls": 5},
}

def rank(weights):
    totals = {t: sum(weights[c] * s[c] for c in weights) for t, s in scores.items()}
    return sorted(totals.items(), key=lambda kv: -kv[1])   # best first

base = {"quality": 0.5, "cost": 0.3, "controls": 0.2}
print("base weights", base)
for t, v in rank(base):
    print(" ", t, round(v, 2))

# Sensitivity: move 0.1 of weight from quality to cost and see if the winner changes
shifted = {"quality": 0.4, "cost": 0.4, "controls": 0.2}
print("shifted weights", shifted)
for t, v in rank(shifted):
    print(" ", t, round(v, 2))
print("winner stable:", rank(base)[0][0] == rank(shifted)[0][0])

# Policy as data: each data class has the minimum approved tool tier allowed to see it
TIERS = {"none": 0, "enterprise": 1, "approved-regulated": 2}
POLICY = {                       # class -> tier required (None = never allowed)
    "public": "none",
    "internal": "enterprise",
    "confidential": "enterprise",
    "regulated": "approved-regulated",
    "secret": None,
}

def allowed(data_class, tool_tier):
    need = POLICY[data_class]
    if need is None:
        return False             # secrets are never sent to any tool
    return TIERS[tool_tier] >= TIERS[need]

for cls in POLICY:
    for tier in ["none", "enterprise", "approved-regulated"]:
        print(f"{cls:12s} {tier:19s} -> {'ALLOW' if allowed(cls, tier) else 'DENY'}")
